from typing import TypedDict, List, Dict, Any, Optional


class CritiqueResult(TypedDict, total=False):
    """Structured evaluation generated by the critic node."""
    is_valid: bool
    feedback: str
    hallucination_score: float


class AgentWorkflowState(TypedDict, total=False):
    """
    Enterprise LangGraph Workflow State tracking the multi-agent reasoning loop.
    Passed sequentially across Planner, Researcher, Synthesizer, and Critic nodes.
    """
    task_id: str
    tenant_id: str
    user_prompt: str
    trace_id: str
    document_ids: List[str]
    metadata: Dict[str, Any]
    plan: List[str]
    research_data: List[Dict[str, Any]]
    draft_report: str
    critique: Dict[str, Any]
    iteration_count: int
    current_node: str
    status: str
    error: Optional[str]

